{
  "name": "@maiife-ai-pub/workbench-tether",
  "version": "0.1.5",
  "description": "Gradus Workbench tether for opencode — presence, plan-time overlap prevention, and landing-queue submission for team-coordinated coding agents",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./client": {
      "types": "./dist/client.d.ts",
      "import": "./dist/client.js"
    },
    "./helpers": {
      "types": "./dist/helpers.d.ts",
      "import": "./dist/helpers.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "lint": "tsc --noEmit",
    "test": "vitest run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gradus",
    "vibecop",
    "multiplayer",
    "coding-agent"
  ],
  "engines": {
    "node": ">=20"
  },
  "homepage": "https://maiife.ai",
  "author": "Maiife <contact@maiife.ai> (https://maiife.ai)",
  "license": "MIT",
  "devDependencies": {
    "typescript": "^5.6.0",
    "vitest": "^4.0.0"
  }
}
